// Automatic proposal checklist, generated by Claude from the grant's
// requirements and saved per organization, grant and language. Checking an
// item off persists for the whole team.
import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useServerFn } from "@tanstack/react-start";
import {
  AlertTriangle,
  CheckCircle2,
  Circle,
  ExternalLink,
  Loader2,
  RefreshCw,
  ShieldCheck,
  Sparkles,
} from "lucide-react";
import {
  generateGrantChecklist,
  getGrantChecklist,
  toggleGrantChecklistItem,
  type ChecklistItem,
} from "@/lib/grant-checklist.functions";
import { useTr, useUiLang } from "@/lib/ui-lang";

const CATEGORY_ORDER: ChecklistItem["category"][] = [
  "document",
  "budget",
  "partner",
  "task",
  "other",
];

export function GrantChecklistPanel({ grantId, orgId }: { grantId: string; orgId: string }) {
  const tr = useTr();
  const lang = useUiLang();
  const queryClient = useQueryClient();
  const fetchChecklist = useServerFn(getGrantChecklist);
  const generate = useServerFn(generateGrantChecklist);
  const toggle = useServerFn(toggleGrantChecklistItem);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const key = ["grant-checklist", grantId, orgId, lang];
  const {
    data,
    isLoading,
    error: loadError,
  } = useQuery({
    queryKey: key,
    queryFn: () => fetchChecklist({ data: { grantId, orgId, lang } }),
  });
  const saved = data?.saved ?? null;

  const onGenerate = async () => {
    setBusy(true);
    setErr(null);
    try {
      await generate({ data: { grantId, orgId, lang } });
      await queryClient.invalidateQueries({ queryKey: key });
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  };

  const onToggle = async (item: ChecklistItem) => {
    // Optimistic flip; the server persists it for the whole organization.
    queryClient.setQueryData(key, (current: typeof data) => ({
      ...current,
      saved: saved
        ? {
            ...saved,
            items: saved.items.map((it) => (it.id === item.id ? { ...it, done: !it.done } : it)),
          }
        : null,
    }));
    try {
      const result = await toggle({
        data: { grantId, orgId, lang, itemId: item.id, done: !item.done },
      });
      queryClient.setQueryData(key, (current: typeof data) => ({
        ...current,
        saved: current?.saved ? { ...current.saved, items: result.items } : current?.saved,
      }));
    } catch {
      await queryClient.invalidateQueries({ queryKey: key });
    }
  };

  const doneCount = saved?.items.filter((it) => it.done).length ?? 0;
  const categoryLabel = (c: ChecklistItem["category"]) =>
    ({
      document: tr("Document", "Documento"),
      budget: tr("Budget", "Presupuesto"),
      partner: tr("Partners", "Socios"),
      task: tr("Task", "Tarea"),
      other: tr("Other", "Otro"),
    })[c];
  const basis = (item: ChecklistItem) => {
    if (item.basis === "published")
      return {
        label: tr("Published requirement", "Requisito publicado"),
        className: "border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300",
        icon: ShieldCheck,
      };
    if (item.basis === "verify")
      return {
        label: tr("Verify", "Por verificar"),
        className: "border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-300",
        icon: AlertTriangle,
      };
    return {
      label: tr("Recommended work", "Trabajo recomendado"),
      className: "border-border bg-muted/50 text-muted-foreground",
      icon: Sparkles,
    };
  };

  return (
    <section className="rounded-xl border bg-card p-5 shadow-sm">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-sm font-semibold">
            {tr("Proposal checklist", "Lista de verificación de la propuesta")}
          </h2>
          <p className="mt-0.5 text-xs text-muted-foreground">
            {saved
              ? tr(
                  `${doneCount} of ${saved.items.length} done · organised with Claude`,
                  `${doneCount} de ${saved.items.length} listos · organizada con Claude`,
                )
              : tr(
                  "Claude organises extracted requirements, recommended work and facts that still need verification.",
                  "Claude organiza requisitos extraídos, trabajo recomendado y hechos que aún deben verificarse.",
                )}
          </p>
        </div>
        <button
          type="button"
          onClick={onGenerate}
          disabled={busy || data?.available === false}
          className="inline-flex items-center gap-2 rounded-md bg-primary px-3.5 py-2 text-xs font-semibold text-primary-foreground transition-opacity disabled:opacity-60"
        >
          {busy ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : saved ? (
            <RefreshCw className="h-3.5 w-3.5" />
          ) : (
            <Sparkles className="h-3.5 w-3.5" />
          )}
          {busy
            ? tr("Claude is working…", "Claude está trabajando…")
            : saved
              ? tr("Regenerate", "Regenerar")
              : tr("Generate with Claude", "Generar con Claude")}
        </button>
      </div>

      {err && (
        <div className="mt-3 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive">
          {err}
        </div>
      )}

      {loadError && (
        <div className="mt-3 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive">
          {loadError instanceof Error ? loadError.message : String(loadError)}
        </div>
      )}

      {data?.available === false && (
        <div className="mt-3 rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-800 dark:text-amber-200">
          {tr(
            "The checklist database migration is not installed yet.",
            "La migración de la lista de verificación aún no está instalada.",
          )}
        </div>
      )}

      {isLoading && !saved && (
        <div className="mt-4 flex items-center gap-2 text-xs text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          {tr("Loading…", "Cargando…")}
        </div>
      )}

      {saved && (
        <ol className="mt-4 space-y-1.5">
          {CATEGORY_ORDER.map((cat) => {
            const group = saved.items.filter((it) => it.category === cat);
            if (!group.length) return null;
            return (
              <li key={cat}>
                <p className="mb-1 mt-3 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                  {categoryLabel(cat)}
                </p>
                <ul className="space-y-1">
                  {group.map((item) => (
                    <li
                      key={item.id}
                      className="rounded-md border border-transparent hover:border-border/60"
                    >
                      <button
                        type="button"
                        onClick={() => onToggle(item)}
                        className="flex w-full items-start gap-2.5 rounded-md px-2 py-1.5 text-left transition-colors hover:bg-muted/60"
                      >
                        {item.done ? (
                          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-teal-600" />
                        ) : (
                          <Circle className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
                        )}
                        <span className="min-w-0">
                          <span
                            className={`block text-sm font-medium ${item.done ? "text-muted-foreground line-through" : ""}`}
                          >
                            {item.label}
                          </span>
                          {item.detail && (
                            <span className="block text-xs text-muted-foreground">
                              {item.detail}
                            </span>
                          )}
                          <span className="mt-1 flex flex-wrap items-center gap-1.5">
                            {(() => {
                              const meta = basis(item);
                              const Icon = meta.icon;
                              return (
                                <span
                                  className={`inline-flex items-center gap-1 rounded-full border px-1.5 py-0.5 text-[10px] font-medium ${meta.className}`}
                                >
                                  <Icon className="h-2.5 w-2.5" /> {meta.label}
                                </span>
                              );
                            })()}
                            {item.requirementRefs.length > 0 && (
                              <span className="text-[10px] text-muted-foreground">
                                {tr("Requirement", "Requisito")} {item.requirementRefs.join(", ")}
                              </span>
                            )}
                          </span>
                        </span>
                      </button>
                      {item.sourceUrls.length > 0 && (
                        <div className="flex flex-wrap gap-2 px-8 pb-1.5">
                          {item.sourceUrls.map((url, index) => (
                            <a
                              key={url}
                              href={url}
                              target="_blank"
                              rel="noreferrer noopener"
                              className="inline-flex items-center gap-1 text-[10px] text-primary hover:underline"
                            >
                              {tr("Source", "Fuente")} {index + 1}
                              <ExternalLink className="h-2.5 w-2.5" />
                            </a>
                          ))}
                        </div>
                      )}
                    </li>
                  ))}
                </ul>
              </li>
            );
          })}
        </ol>
      )}
    </section>
  );
}
